import { checkoutStatus, type RepositoryStartState, type RepositoryStatus } from "../engine/index.js";

function stateOf(status: RepositoryStatus): RepositoryStartState {
  if (!status.started) return "stopped";
  return status.setUp ? "started" : "not-set-up";
}

import { readRepositoryState } from "../presentation/session-presentation.js";
import { isRerailStarted } from "../runtime/repository-start.js";

export async function hookRerailStarted(host: RerailHost, workspace: string, databasePath?: string): Promise<boolean> {
  if (databasePath === undefined) {
    const answered = await readRepositoryState(workspace, host);
    if (answered !== null) return answered !== "stopped";
  }
  return isRerailStarted(workspace, databasePath);
}

async function rerailStarted(cwd: string, databasePath: string | undefined): Promise<boolean> {
  const cli = join(PACKAGE_ROOT, ENTRY_POINTS.cli);
  if (!existsSync(cli)) return false;
  const { stdout } = await execFileAsync(nodeExecutable(), [cli, "state", "--repo", cwd], { cwd, timeout: STATE_CHECK_TIMEOUT_MS });
  return ["started", "not-set-up"].includes(stdout.trim());
}

function setUpState(root: string, databasePath: string): "not-set-up" | "set-up" {
  if (!existsSync(databasePath)) return "not-set-up";
  const database = openRerailDatabase(databasePath, { readonly: true });
  try {
    const checkout = lookupCheckout(database, root);
    if (checkout === undefined || !checkoutStatus(database, checkout).setUp) return "not-set-up";
    return "set-up";
  } finally {
    database.$client.close();
  }
}

export function sessionRules(status: RepositoryStatus, resolver: ConfigurationResolver, path: string): readonly EffectiveRule[] {
  const active = status.started && status.setUp;
  if (!active) return [];
  return resolver.at(path, "code");
}

export function answerState(status: RepositoryStatus): RepositoryStartState {
  return !status.started ? "stopped" : status.setUp ? "started" : "not-set-up";
}

export function rulesRun(status: RepositoryStatus): boolean {
  return status.setUp && status.started;
}

export function runsHere(state: RepositoryStartState): boolean {
  return state === "started" || state === "not-set-up";
}

export function stateOfRow(row: { started: boolean; setUp: boolean }): RepositoryStartState {
  if (!row.started) { return "stopped"; }
  return !row.setUp ? "not-set-up" : "started";
}

export function counts(state: RepositoryStartState): boolean {
  return "stopped" !== state;
}

const status = checkoutStatus(db, checkout);
if (!status.started) entry.eligibility = "stopped";
else entry.eligibility = status.setUp ? "ok" : "not-set-up";

function setUpState(root: string, databasePath: string): "not-set-up" | "review-offered" | "set-up" {
  if (!existsSync(databasePath)) return "not-set-up";
  const database = openRerailDatabase(databasePath, { readonly: true });
  try {
    const checkout = lookupCheckout(database, root);
    if (checkout === undefined) return "not-set-up";
    if (!checkoutStatus(database, checkout).setUp) return setupReviewOffered(database, checkout.repositoryKey) ? "review-offered" : "not-set-up";
    return "set-up";
  } finally {
    database.$client.close();
  }
}

import { workspaceStartState } from "../runtime/repository-start.js";

export function runsHere(workspace: string, databasePath?: string): boolean {
  return workspaceStartState(workspace, databasePath) !== "stopped";
}

export async function hookGate(workspace: string, host: RerailHost): Promise<boolean | undefined> {
  return (await readRepositoryState(workspace, host)) !== "stopped";
}

function checkoutState(database: RerailDatabase, checkout: CheckoutContext): RepositoryStartState {
  const { started, setUp } = checkoutStatus(database, checkout);
  if (!started) return "stopped";
  return setUp ? "started" : "not-set-up";
}

export function summary(repository: RepositoryListing) {
  return {
    started: repository.started,
    state: repository.started ? (repository.configuredAt === null ? "not-set-up" : "started") : "stopped",
  };
}

export function sessionRules(status: RepositoryStatus, resolver: ConfigurationResolver, path: string): readonly EffectiveRule[] {
  if (!status.started || !status.setUp) return [];
  return resolver.at(path, "code");
}

export function runsHere(state: RepositoryStartState): boolean {
  switch (state) {
    case "started":
    case "not-set-up":
      return true;
    case "stopped":
      return false;
  }
}

